package chatui

const ChatgateStyles = `.chatgate-overlay{position:fixed;inset:0;z-index:1000;background:var(--hcm-color-canvas);overflow:auto;padding:clamp(.5rem,3vw,2rem)}.chatgate{max-inline-size:54rem;margin-inline:auto;color:var(--hcm-color-text);background:var(--hcm-color-surface);border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);padding:1rem;min-inline-size:0}.chatgate *{box-sizing:border-box;min-inline-size:0}.chatgate h2,.chatgate p,.chatgate label{overflow-wrap:anywhere}.chatgate fieldset{border:1px solid var(--hcm-color-border);margin-block:1rem;padding:.75rem;border-radius:var(--hcm-radius-control)}.chatgate label{display:block;margin-block:.5rem}.chatgate input,.chatgate select,.chatgate textarea{display:block;width:100%;max-inline-size:100%;min-block-size:44px;background:var(--hcm-color-canvas);color:var(--hcm-color-text);border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);padding:.5rem}.chatgate input[type=checkbox]{display:inline-block;width:44px;vertical-align:middle}.chatgate button,.chatgate a{min-block-size:44px;display:inline-flex;align-items:center;padding:.5rem .75rem;border-radius:var(--hcm-radius-control);color:var(--hcm-color-text);background:var(--hcm-color-surface);border:1px solid var(--hcm-color-border);white-space:normal;overflow-wrap:anywhere}.chatgate .primary{background:var(--hcm-color-brand-primary);color:var(--hcm-color-on-brand)}.chatgate :focus-visible{outline:3px solid var(--hcm-color-focus);outline-offset:2px}.chatgate-actions{display:flex;flex-wrap:wrap;gap:.5rem;margin-block:.75rem}.chatgate-hint{color:var(--hcm-color-text-muted)}.chatgate-error{color:var(--hcm-color-danger);min-block-size:1.5rem}.chatgate-table-wrap{overflow:auto;max-inline-size:100%}.chatgate table{width:100%;border-collapse:collapse}.chatgate td,.chatgate th{text-align:start;padding:.5rem;overflow-wrap:anywhere}.chatgate pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:400px){.chatgate{padding:.5rem}.chatgate-actions>*{flex:1 1 100%}}@media(prefers-reduced-motion:reduce){.chatgate *{animation:none;transition:none}}`
